"""Local minimum-norm corrections to ball position and lateral release velocity."""
import argparse,json
import numpy as np,mw_tool


def main():
    p=argparse.ArgumentParser();p.add_argument('--input',required=True);p.add_argument('--output',required=True)
    p.add_argument('--nmove',type=int,default=16);p.add_argument('--degree',type=int,default=4)
    p.add_argument('--iterations',type=int,default=40);p.add_argument('--step',type=float,default=1e-6)
    args=p.parse_args();s=mw_tool.Session();a=np.load(args.input)['actions'].copy();cutoff=len(a)-9-args.nmove
    basis=np.polynomial.legendre.legvander(np.linspace(-1,1,args.nmove),args.degree-1)
    goal=np.r_[s.target_pos[:2],.3];x=np.zeros(args.degree*3);best=1e9
    def evaluate(x):
        b=a.copy();b[cutoff:cutoff+args.nmove,:3]+=basis@x.reshape(args.degree,3);s.replay(np.clip(b,-1,1))
        return np.r_[(s.obs[4:7]-goal)*[1,1,2],s.data.qvel[-6:-4]*.05]
    for iteration in range(args.iterations):
        e=evaluate(x);norm=np.linalg.norm(e)
        if s.check()['success'] and norm<best:
            best=norm;s.save_trajectory(path=args.output,meta={'parent':args.input,'basis':'legendre',
                'cutoff':cutoff,'coefficients':x.tolist(),'residual_norm':float(norm)})
        print('ITERATION',iteration,'error',norm,'ball',s.obs[4:7],'velocity',s.data.qvel[-6:-3],flush=True)
        if norm<1e-11:break
        jac=np.zeros((5,len(x)))
        h=args.step
        for k in range(len(x)):
            xp=x.copy();xm=x.copy();xp[k]+=h;xm[k]-=h;jac[:,k]=(evaluate(xp)-evaluate(xm))/(2*h)
        dx=np.linalg.lstsq(jac,-e,rcond=1e-5)[0]
        mx=np.max(np.abs(dx))
        if mx>.08:dx*=.08/mx
        improved=False
        for scale in [1.,.5,.25,.1,.03,.01]:
            xn=x+scale*dx;en=evaluate(xn)
            if np.linalg.norm(en)<norm:
                x=xn;improved=True;break
        if not improved:
            args.step*=.25
            if args.step<1e-9:break
    s.close()


if __name__=='__main__':main()
PY","max_output_tokens":1000}));
