"""Smooth native hand commands in the null space of release endpoint constraints."""
import json,numpy as np,mw_tool
from pathlib import Path


def main():
    s=mw_tool.Session();a=np.load('/app/output/robust_pick_newton.npz')['actions'].copy()
    nmove=27;cutoff=len(a)-9-nmove;degree=6
    u=np.linspace(0,1,nmove);basis=np.stack([np.sin(k*np.pi*u) for k in range(1,degree+1)],axis=1)
    goal=np.r_[s.target_pos[:2],.3];x=np.zeros(degree*3);rows=[]
    def actions(x):
        b=a.copy();b[cutoff:cutoff+nmove,:3]+=basis@x.reshape(degree,3);return np.clip(b,-1,1)
    def endpoint(x):
        s.replay(actions(x));return np.r_[(s.obs[4:7]-goal)*[1,1,2],s.data.qvel[-6:-4]*.05]
    def jacobian(x):
        h=1e-5;j=np.empty((5,len(x)))
        for k in range(len(x)):
            p=x.copy();m=x.copy();p[k]+=h;m[k]-=h;j[:,k]=(endpoint(p)-endpoint(m))/(2*h)
        return j
    def objective(x):
        b=actions(x)[:,:3];return float(np.square(np.diff(b,axis=0)).sum()+.01*np.square(b).sum())
    def gradient(x):
        b=actions(x)[:,:3];diff=np.diff(b,axis=0);g=.02*b;g[:-1]-=2*diff;g[1:]+=2*diff
        raw=a[cutoff:cutoff+nmove,:3]+basis@x.reshape(degree,3)
        active=np.abs(raw)<1
        return (basis.T@(g[cutoff:cutoff+nmove]*active)).ravel()
    best=objective(x)
    for i in range(80):
        err=endpoint(x);j=jacobian(x);pinv=np.linalg.pinv(j,rcond=1e-5)
        g=gradient(x);direction=-(g-pinv@(j@g));direction-=pinv@err
        mx=np.max(np.abs(direction))
        if mx>.025:direction*=.025/mx
        accepted=False
        for rate in [1.,.5,.25,.1,.03]:
            y=x+rate*direction;ey=endpoint(y)
            for correction in range(3):
                if np.linalg.norm(ey)<1e-7:break
                dx=-pinv@ey
                if np.max(np.abs(dx))>.05:break
                y+=dx;ey=endpoint(y)
            cost=objective(y)
            if np.linalg.norm(ey)<1e-6 and cost<best-1e-7:
